'use strict';
const $=s=>document.querySelector(s),A=RepoAccount,Q=RepoQuality,E=RepoEditorial,U=RepoAdminUI,esc=U.esc;
const TABS=['editorial','quality','reports','analytics','sync','users','help'];
const RUNNING=['in_progress','queued','waiting','pending','requested'];
const queryTab=new URL(location.href).searchParams.get('tab');
let rows=[],repos=[],repoMap=new Map(),editing=null,selected=[],started=false,busy=false,builtinSetupRequired=false,dirty=false,activeTab=TABS.includes(queryTab)?queryTab:'editorial';
let users=[],userCursor=null,userToken=0,userSearchTimer,projectToken=0,projectTimer,projectCursor=null;
let analyticsToken=0,growthToken=0,syncPage=1,syncToken=0,syncLoading=false,syncAutoRefresh=false,syncLoadedAt=0,catalogueRequest=null,catalogueBlockedReason=null,attentionToken=0;

const svg=(body,size=14)=>`<svg width="${size}" height="${size}" viewBox="0 0 14 14" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${body}</svg>`;
const icon={up:svg('<path d="M3 8.5l4-4 4 4"/>'),down:svg('<path d="M3 5.5l4 4 4-4"/>'),x:svg('<path d="M3.5 3.5l7 7M10.5 3.5l-7 7"/>'),grip:'<svg width="12" height="16" viewBox="0 0 12 16" fill="currentColor" aria-hidden="true"><circle cx="3.5" cy="3" r="1.3"/><circle cx="8.5" cy="3" r="1.3"/><circle cx="3.5" cy="8" r="1.3"/><circle cx="8.5" cy="8" r="1.3"/><circle cx="3.5" cy="13" r="1.3"/><circle cx="8.5" cy="13" r="1.3"/></svg>'};
const message=(text,error=false)=>{const el=$('#admin-message');el.textContent=text;el.classList.toggle('error',error);el.setAttribute('role',error?'alert':'status')};
const fail=e=>{if(e.status===401||e.status===403)return A.refresh()};

/* ---------- access gate ---------- */
function gate(){if(!A.ready)return;if(!A.user?.admin){catalogueRequest=null;analyticsToken++;syncToken++;userToken++;attentionToken++;started=false;dirty=false;projectToken++;repoMap.clear();repos=[];rows=[];editing=null;selected=[];users=[];for(const id of ['#analytics-content','#users-content','#sync-content','#help-content'])U.clear($(id));for(const name of ['quality','reports','sync'])U.flag(name,null);$('#admin-workspace').hidden=true;$('#admin-gate').hidden=false;$('#admin-gate').innerHTML=`<h1>${A.user?'Administrator access required':A.enabled?'Sign in to your workspace':'Administration is being set up'}</h1><p>${A.user?'Your account can save likes. Storefront editing and analytics require an administrator role.':A.enabled?'Use the GitHub account that has been granted administrator access.':'The storefront is available while account setup is completed.'}</p>${!A.user&&A.enabled?'<a class="button lime" href="/api/auth?action=start&return=%2Fadmin.html">Sign in with GitHub ↗</a><p class="small">By signing in you agree to our <a href="/terms.html">Terms of Service</a> and acknowledge our <a href="/privacy.html">Privacy Policy</a>.</p>':''}<a class="button outline" href="/">Home</a>`;return}$('#admin-gate').hidden=true;$('#admin-workspace').hidden=false;if(!started){started=true;void initialize();activateTab(activeTab,false)}}

/* ---------- storefront editor ---------- */
const migration8='<a href="https://github.com/sparx1981/RepoShelf/blob/main/supabase/migrations/202610040008_editorial_discovery_qa.sql" target="_blank" rel="noopener">migration 8</a>';
function applyEditorial(data){builtinSetupRequired=data.builtinSetupRequired===true;rows=E.resolve(data.rows);$('#editorial-setup').hidden=!builtinSetupRequired;$('#editorial-setup').innerHTML=`Built-in rows are read-only until ${migration8} is applied in Supabase. Existing custom rows remain available.`;$('#custom-rows').checked=data.customRows;renderRows()}
async function initialize(){message('Loading your workspace…');try{const [data,browse]=await Promise.all([A.request('/api/editorial?manage=1'),A.request('/api/editorial?action=browse&manage=1',{method:'POST',body:JSON.stringify({demos:false,limit:30})})]);if(!A.user?.admin)return;repos=browse.items;repoMap=new Map(repos.map(r=>[r.full,r]));$('#row-category').innerHTML='<option value="">Any category</option>'+[...new Set([...E.categories,...Object.keys(browse.facets.categories)])].sort().map(x=>`<option>${esc(x)}</option>`).join('');applyEditorial(data);reset(true);message('');void loadAttention()}catch(e){message(e.message,true)}}
async function reload(){const data=await A.request('/api/editorial?manage=1');if(!A.user?.admin)return;applyEditorial(data)}
function renderRows(){const movable=rows.filter(r=>!builtinSetupRequired||!r.builtin_key);$('#row-list').innerHTML=rows.length?rows.map(row=>{const i=movable.findIndex(r=>r.id===row.id),locked=builtinSetupRequired&&row.builtin_key,mode=row.mode==='manual'?`${row.items.length} selected project${row.items.length===1?'':'s'}`:esc(E.modes[row.mode]||row.mode);return `<article class="row-tile" ${locked?'':'data-sortable'}><div class="row-tile-head">${locked?'':`<span class="drag-handle" data-drag-handle title="Drag to reorder">${icon.grip}</span>`}<div class="row-tile-title"><h3>${esc(row.title)}</h3><p>${row.builtin_key?'Built-in · ':''}${mode}${row.category?' · '+esc(row.category):''}</p></div>${U.pill(row.enabled?'published':'draft',row.enabled?'Published':'Draft',row.enabled?'ok':'neutral')}</div><div class="row-tile-actions"><button data-edit="${row.id}">Edit</button><span class="btn-pair"><button data-move="${row.id}" data-step="-1" aria-label="Move ${esc(row.title)} up" ${locked||i<=0?'disabled':''}>${icon.up}</button><button data-move="${row.id}" data-step="1" aria-label="Move ${esc(row.title)} down" ${locked||i===movable.length-1?'disabled':''}>${icon.down}</button></span><button data-publish="${row.id}" ${locked?'disabled':''}>${row.enabled?'Unpublish':'Publish'}</button>${row.builtin_key?'':`<button class="danger push-end" data-delete="${row.id}">Delete</button>`}</div></article>`}).join(''):'<p class="small">Create your first category row. Start with a draft and publish when it is ready.</p>'}
function updateState(){const publishing=editing?.enabled===true;$('#row-state').innerHTML=dirty?U.pill('attention','Unsaved changes','warn'):U.pill(publishing?'published':'draft',publishing?'Published':'Draft',publishing?'ok':'neutral')}
function setDirty(value){dirty=value;updateState()}
function confirmDiscard(){return !dirty||confirm('Discard your unsaved changes to this row?')}
function reset(force=false){if(!force&&!confirmDiscard())return;editing=null;selected=[];$('#row-form').reset();$('#editor-title').textContent='Create a row';dirty=false;updateState();renderSelection();searchProjects();updateMode()}
function edit(row,force=false){if(!force&&!confirmDiscard())return;editing={...row};selected=[...row.items];$('#editor-title').textContent='Edit row';$('#row-title').value=row.title;$('#row-description').value=row.description;$('#row-category').value=row.category;$('#row-mode').value=row.mode;$('#row-enabled').checked=row.enabled;dirty=false;updateState();renderSelection();void hydrateSelection(selected);void searchProjects();updateMode();$('#row-title').focus()}
function values(){return {builtin_key:editing?.builtin_key,id:editing?.id,revision:editing?.revision,title:$('#row-title').value,description:$('#row-description').value,category:$('#row-category').value,mode:$('#row-mode').value,enabled:$('#row-enabled').checked,items:selected}}
function renderSelection(){$('#selection-count').textContent=`${selected.length} of 120 selected`;$('#selected-projects').innerHTML=selected.length?selected.map((id,i)=>`<div class="selected-project" data-sortable><span class="drag-handle" data-drag-handle title="Drag to reorder">${icon.grip}</span><span class="selected-name">${esc(repoMap.get(id)?.name||id)}<small>${esc(id)}${!repoMap.has(id)?' · Details not loaded':''}</small></span><button type="button" data-selected-move="${i}" data-step="-1" aria-label="Move ${esc(id)} up" ${i===0?'disabled':''}>${icon.up}</button><button type="button" data-selected-move="${i}" data-step="1" aria-label="Move ${esc(id)} down" ${i===selected.length-1?'disabled':''}>${icon.down}</button><button type="button" data-remove="${i}" aria-label="Remove ${esc(id)}">${icon.x}</button></div>`).join(''):'<p class="small">Choose the projects that belong on this shelf.</p>'}
async function searchProjects(append=false){const token=++projectToken;if(!append)projectCursor=null;try{const data=await A.request('/api/editorial?action=browse&manage=1',{method:'POST',body:JSON.stringify({q:$('#project-search').value,category:$('#row-category').value,demos:false,limit:30,cursor:append?projectCursor:null})});if(token!==projectToken||!A.user?.admin)return;repos=append?[...repos,...data.items]:data.items;projectCursor=data.nextCursor;for(const r of data.items)repoMap.set(r.full,r);$('#project-results').innerHTML=repos.map(r=>`<button type="button" class="project-choice" data-select="${esc(r.full)}" ${selected.includes(r.full)?'disabled':''}><strong>${esc(r.name)}</strong><small>${esc(r.category)} · ${esc(r.full)} · ${esc(Q.catalogueState(r))}</small></button>`).join('')||'<p class="small">No matching projects.</p>';if(projectCursor)$('#project-results').insertAdjacentHTML('beforeend','<button type="button" class="button outline" data-more-projects>Show more projects</button>');renderSelection()}catch(e){if(token===projectToken&&A.user?.admin)message(e.message,true)}}
async function hydrateSelection(ids){await Promise.all(ids.filter(id=>!repoMap.has(id)).map(async id=>{try{const data=await A.request('/api/editorial?action=detail&id='+encodeURIComponent(id));if(A.user?.admin)repoMap.set(id,data.repo)}catch{}}));if(A.user?.admin)renderSelection()}
const modeHints={manual:'You choose the projects and their order.',popular:'GitHub stars and forks, or Hugging Face Space likes.',reposhelf:'Listing clicks on RepoShelf in the last 30 days.',trending:'GitHub star and fork growth over roughly the last week.',newest:'Most recently created or updated projects.',random:'A new order on each page load, stable while browsing.',daily:'One shared order per UTC day, changing at midnight UTC.',community:'Hacker News and Bluesky mentions in the last 30 days.',releases:'GitHub releases from the last 30 days.'};
function updateMode(){const mode=$('#row-mode').value,manual=mode==='manual';$('#mode-hint').innerHTML=esc(modeHints[mode]||'')+' <button type="button" class="help-inline-button" data-admin-tab="help">How ranking works</button>';$('#manual-selection').hidden=!manual;$('#automatic-note').hidden=manual}
async function task(fn){if(busy)return;busy=true;$('#save-row').disabled=true;try{await fn()}catch(e){message(e.message,true);if(e.status===409)await reload();await fail(e)}finally{busy=false;$('#save-row').disabled=false}}
async function moveRow(from,to){const movable=rows.filter(r=>!builtinSetupRequired||!r.builtin_key),ids=movable.map(r=>r.id);if(from<0||to<0||from>=ids.length||to>=ids.length||from===to)return;ids.splice(to,0,ids.splice(from,1)[0]);await task(async()=>{await A.request('/api/editorial',{method:'POST',body:JSON.stringify({action:'reorder',ids})});await reload();if(editing){const current=rows.find(r=>r.id===editing.id);if(current)editing={...current}}message('Row order updated.')})}
function sortable(container,onMove){let from=null;const items=()=>[...container.querySelectorAll('[data-sortable]')],clean=()=>{for(const el of container.querySelectorAll('.is-dragging,.drop-target'))el.classList.remove('is-dragging','drop-target');for(const el of items())el.removeAttribute('draggable')};
container.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-drag-handle]');if(handle)handle.closest('[data-sortable]')?.setAttribute('draggable','true')});
container.addEventListener('dragstart',e=>{const item=e.target.closest?.('[data-sortable]');if(!item||item.getAttribute('draggable')!=='true')return;from=items().indexOf(item);item.classList.add('is-dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(from))});
container.addEventListener('dragover',e=>{if(from===null)return;e.preventDefault();for(const el of container.querySelectorAll('.drop-target'))el.classList.remove('drop-target');e.target.closest('[data-sortable]')?.classList.add('drop-target')});
container.addEventListener('drop',e=>{if(from===null)return;e.preventDefault();const to=items().indexOf(e.target.closest('[data-sortable]')),start=from;from=null;clean();if(to>=0&&to!==start)onMove(start,to)});
container.addEventListener('dragend',()=>{from=null;clean()});container.addEventListener('pointerup',()=>{if(from===null)for(const el of items())el.removeAttribute('draggable')})}
sortable($('#row-list'),(from,to)=>void moveRow(from,to));
sortable($('#selected-projects'),(from,to)=>{selected.splice(to,0,selected.splice(from,1)[0]);setDirty(true);renderSelection()});
$('#row-form').addEventListener('input',e=>{if(e.target.id!=='project-search')setDirty(true)});
$('#row-form').onsubmit=e=>{e.preventDefault();void task(async()=>{if(builtinSetupRequired&&(editing?.builtin_key||['random','daily','community','releases'].includes($('#row-mode').value))){message('Apply migration 8 in Supabase, then refresh this page to save these settings.',true);return}message('Saving row…');const data=await A.request('/api/editorial',{method:'POST',body:JSON.stringify({row:values()})});await reload();edit(data.row,true);message(data.row.enabled?'Published. The row is available on the storefront.':'Draft saved.')})};
$('#new-row').onclick=()=>reset();$('#reset-row').onclick=()=>reset();$('#project-search').oninput=()=>{clearTimeout(projectTimer);projectTimer=setTimeout(()=>void searchProjects(),250)};$('#row-category').onchange=searchProjects;$('#row-mode').onchange=updateMode;
$('#custom-rows').onchange=e=>void task(async()=>{await A.request('/api/editorial',{method:'POST',body:JSON.stringify({action:'settings',customRows:e.target.checked})});const text=e.target.checked?'Custom rows enabled; built-in feature ribbons remain editable.':'Built-in category rows restored.';message(text);U.toast(text)});
$('#admin-signout').onclick=()=>void A.signout().catch(e=>message(e.message,true));
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});

document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.id==='catalogue-sync-now'||b.id==='catalogue-publish-now'){e.preventDefault();void requestCatalogueWorkflow(b.id==='catalogue-sync-now'?'sync':'publish');return}
 if(b.dataset.retry){retry(b.dataset.retry);return}
 if(b.hasAttribute('data-more-projects')){void searchProjects(true);return}
 if(b.dataset.adminTab){activateTab(b.dataset.adminTab);return}
 if(b.dataset.roleUser){void changeRole(b.dataset.roleUser);return}
 if(b.dataset.select){if(selected.length>=120){message('This row can contain up to 120 selected projects.',true);return}selected.push(b.dataset.select);setDirty(true);renderSelection();searchProjects();return}
 if(b.dataset.remove!==undefined){selected.splice(Number(b.dataset.remove),1);setDirty(true);renderSelection();searchProjects();return}
 if(b.dataset.selectedMove!==undefined){const i=Number(b.dataset.selectedMove),j=i+Number(b.dataset.step);[selected[i],selected[j]]=[selected[j],selected[i]];setDirty(true);renderSelection();return}
 if(b.dataset.edit){edit(rows.find(r=>r.id===b.dataset.edit));return}
 if(b.dataset.move){const movable=rows.filter(r=>!builtinSetupRequired||!r.builtin_key),i=movable.findIndex(r=>r.id===b.dataset.move);void moveRow(i,i+Number(b.dataset.step));return}
 if(b.dataset.publish)void task(async()=>{const row=rows.find(r=>r.id===b.dataset.publish);await A.request('/api/editorial',{method:'POST',body:JSON.stringify({row:{...row,enabled:!row.enabled}})});await reload();if(editing?.id===row.id&&!dirty){editing={...rows.find(r=>r.id===row.id)};$('#row-enabled').checked=editing.enabled;updateState()}message(row.enabled?'Row unpublished.':'Row published.')});
 if(b.dataset.delete){const row=rows.find(r=>r.id===b.dataset.delete);if(confirm(`Delete the “${row.title}” row? Projects remain in the catalogue.`))void task(async()=>{await A.request('/api/editorial',{method:'DELETE',body:JSON.stringify({id:row.id,revision:row.revision})});if(editing?.id===row.id)reset(true);await reload();message('Row deleted.')})}});
function retry(name){if(name==='analytics')void loadAnalytics();else if(name==='sync')void loadSyncLog();else if(name==='users')void loadUsers();else if(name==='help')void loadHelp()}

/* ---------- analytics ---------- */
function metric(value,label,note=''){return `<div class="metric"><strong>${value===null||value===undefined?'—':Number(value||0).toLocaleString()}</strong><span>${esc(label)}</span>${note?`<small class="metric-note">${esc(note)}</small>`:''}</div>`}
function chart(data,key,label,{zero=false}={}){if(!data.length)return '<p class="chart-empty">History will appear as refreshes complete.</p>';const values=data.map(r=>Number(r[key]||0)),min=zero?0:Math.min(...values),max=Math.max(...values),range=max-min||1,x=i=>20+i/Math.max(1,values.length-1)*660,y=v=>145-(v-min)/range*115,points=values.map((v,i)=>`${x(i)},${y(v)}`).join(' ');return `<svg viewBox="0 0 700 175" role="img" aria-label="${esc(label)}: ${values[0]} to ${values.at(-1)}"><path class="chart-base" d="M20 145H680"/><polyline class="chart-line" fill="none" stroke-width="3" stroke-linejoin="round" points="${points}"/>${data.map((r,i)=>`<circle class="chart-dot" cx="${x(i)}" cy="${y(values[i])}" r="4"><title>${esc(r.day||r.at)}: ${values[i].toLocaleString()}</title></circle>`).join('')}</svg><div class="chart-axis"><span>${esc((data[0].day||data[0].at).slice(0,10))}</span><span>${esc((data.at(-1).day||data.at(-1).at).slice(0,10))}</span></div><p class="chart-scale">${min.toLocaleString()} to ${max.toLocaleString()}${zero?'':' · axis starts at the lowest value'}</p>`}
function halves(daily,key){if(daily.length<4)return '';const mid=Math.floor(daily.length/2),sum=list=>list.reduce((n,r)=>n+Number(r[key]||0),0),a=sum(daily.slice(0,mid)),b=sum(daily.slice(mid));if(!a&&!b)return '';if(!a)return 'New in the second half of the range';const pct=Math.round((b-a)/a*100);return pct===0?'Level with the first half of the range':`${pct>0?'Up':'Down'} ${Math.abs(pct).toLocaleString()}% on the first half of the range`}
document.addEventListener('change',async event=>{if(event.target.id!=='growth-sort'||!A.user?.admin)return;const token=analyticsToken,request=++growthToken,select=event.target;select.disabled=true;$('#growth-status').textContent='Updating ranking…';try{const data=await A.request('/api/analytics?action=popularity&sort='+encodeURIComponent(select.value));if(token!==analyticsToken||request!==growthToken||!A.user?.admin)return;$('#popularity-growth').outerHTML=RepoGrowthAnalytics.render(data)}catch(e){if(token===analyticsToken&&request===growthToken&&A.user?.admin){$('#growth-status').textContent=e.message;select.disabled=false}await fail(e)}});
const MCP_LABELS={search_projects:'Search projects',get_project_context:'Project context',read_project_document:'Read document',find_related_projects:'Related projects',compare_projects:'Compare projects',get_setup_requirements:'Setup requirements',get_demo_info:'Demo info',browse_catalog:'Browse catalogue',get_catalog_info:'Catalogue info',prompt_find_starting_points:'Prompt: find starting points',prompt_compare_candidates:'Prompt: compare candidates',prompt_check_before_reuse:'Prompt: check before reuse'};
function renderConnectorUsage(c,days){const head=`<section class="analytics-box"><h3>AI connector usage</h3>`;if(!c||c.state==='not_configured')return head+'<p class="chart-empty">Configure the Supabase server key to count connector use.</p></section>';if(c.state==='migration_required')return head+'<p class="chart-empty">Apply migration 17 in Supabase to count connector use and share the rate limit across servers.</p></section>';if(c.state!=='ready')return head+'<p class="chart-empty">Connector usage could not be read. Check the Supabase configuration.</p></section>';const totals=new Map();for(const r of c.rows)totals.set(r.tool,(totals.get(r.tool)||0)+r.calls);const rows=[...totals].sort((a,b)=>b[1]-a[1]),sum=rows.reduce((n,[,v])=>n+v,0);return head+(rows.length?`<div class="metric-grid">${metric(sum,'Tool and prompt calls')}${metric(rows.length,'Different tools used')}</div><div class="help-table-wrap"><table class="analytics-table"><thead><tr><th>Tool</th><th class="num">Calls</th></tr></thead><tbody>${rows.map(([tool,calls])=>`<tr><td>${esc(MCP_LABELS[tool]||tool)}</td><td class="num">${calls.toLocaleString()}</td></tr>`).join('')}</tbody></table></div>`:'<p class="chart-empty">No connector calls in this period yet.</p>')+`<p class="analytics-caption">Counts are totals per tool for the last ${Number(days)} days. They contain no caller, query or project information.</p></section>`}
function renderAnalytics(data,days){const daily=data.daily||[],total=key=>daily.reduce((n,r)=>n+Number(r[key]||0),0),cutoff=Date.parse(new Date().toISOString().slice(0,10)+'T00:00:00Z')-(days-1)*86400000,growth=(data.growth||[]).filter(r=>Date.parse(r.at)>=cutoff),series=(key,label)=>metric(total(key),label,halves(daily,key));
 return `<p class="analytics-caption">Administrator activity is excluded. Visitor statistics require analytics consent and respect browser privacy settings.${data.checkedAt?' Data checked '+esc(new Date(data.checkedAt).toLocaleString())+'.':''}</p>${data.delivery?.state==='error'||data.delivery?.state==='not_configured'?`<p class="analytics-caption" role="status">${esc(data.delivery.message)}</p>`:data.delivery?.state==='ready'?`<p class="analytics-caption">${data.delivery.lastEventAt?'Last visitor event received: '+esc(new Date(data.delivery.lastEventAt).toLocaleString())+'.':'Storage is connected. No eligible visitor events have been received yet.'}</p>`:''}${!data.trackingEnabled?'<p class="analytics-caption">Visit tracking is awaiting activation. Catalogue coverage is available below.</p>':''}
<section class="analytics-group"><h3>Traffic</h3><div class="metric-grid">${metric(data.uniqueVisitors??null,'Unique visitors')}${series('visits','Visits')}${series('page_views','Page views')}${series('listing_views','Listing views')}</div></section>
<section class="analytics-group"><h3>Engagement</h3><div class="metric-grid">${series('demo_clicks','Demo clicks')}${series('fork_clicks','Fork / duplicate clicks')}${series('searches','Searches')}${metric(data.totalLikes,'Current saved likes')}${metric(data.likesAdded,'Likes added and still saved')}</div></section>
<div class="analytics-grid"><section class="analytics-box"><h3>Page views over time</h3>${chart(daily,'page_views','Page views',{zero:true})}<details><summary>About these numbers</summary><p class="analytics-caption">${esc(data.visitorMethod)}</p><p class="analytics-caption">${data.uniqueVisitorsSince?'Unique visitor tracking started '+esc(new Date(data.uniqueVisitorsSince).toLocaleString())+'. Earlier visits are excluded from this stat.':'Apply <a href="https://github.com/sparx1981/RepoShelf/blob/main/supabase/migrations/202610030003_unique_visitors.sql" target="_blank" rel="noopener noreferrer">migration 3</a> in Supabase to activate this stat. Existing visit totals remain available.'}</p><p class="analytics-caption">Charts and daily tables use UTC dates; update times use your local time. Likes and library growth are separate from visitor tracking. Fork clicks represent intent, not a confirmed fork. No search text or IP addresses are stored. Daily totals remain; detailed activity is retained for 90 days. Trend notes compare the second half of the selected range with the first.</p></details><details><summary>Daily counts</summary><div class="help-table-wrap"><table class="analytics-table"><thead><tr><th>Date (UTC)</th><th>Visits</th><th>Views</th><th>Visitors</th></tr></thead><tbody>${daily.map(r=>`<tr><td>${esc(r.day)}</td><td>${Number(r.visits)}</td><td>${Number(r.page_views)}</td><td>${Number(r.visitors)}</td></tr>`).join('')}</tbody></table></div></details></section><section class="analytics-box"><h3>Most viewed projects</h3>${data.topListings?.length?`<table class="analytics-table"><thead><tr><th>Project</th><th>Views</th></tr></thead><tbody>${data.topListings.map(r=>`<tr><td>${esc(repoMap.get(r.project_id)?.name||r.project_id)}</td><td>${Number(r.views).toLocaleString()}</td></tr>`).join('')}</tbody></table>`:'<p class="chart-empty">Listing views will appear here.</p>'}</section></div>
${window.RepoLaunchAnalytics?.(data.conversions,rows)||''}${renderConnectorUsage(data.connector,days)}${window.RepoGrowthAnalytics?.render(data.popularity)||''}
<section class="analytics-box"><h3>Library growth</h3><div class="metric-grid">${metric(data.coverage.availableProjects,'Available projects')}${metric(data.coverage.withDemo,'With demos')}${metric(data.coverage.readmesSaved,'Saved READMEs')}${metric(data.coverage.supportingContextsSaved,'Supporting contexts')}</div>${chart(growth,'records','Indexed projects')}<details><summary>Catalogue snapshots</summary><div class="help-table-wrap"><table class="analytics-table"><thead><tr><th>Date (UTC)</th><th>Projects</th><th>Demos</th><th>Previews</th><th>Unavailable</th></tr></thead><tbody>${growth.slice(-30).map(r=>`<tr><td>${esc(r.at.slice(0,16).replace('T',' '))}</td><td>${r.records}</td><td>${r.withDemo}</td><td>${r.withScreenshot}</td><td>${r.unavailable}</td></tr>`).join('')}</tbody></table></div></details><p class="analytics-caption">Growth history starts with this update and is saved after each catalogue refresh.</p></section>`}
async function loadAnalytics(){const token=++analyticsToken,slot=$('#analytics-content'),stamp=$('#analytics-updated');if(!U.loaded(slot))U.show(slot,'<p class="loading-note">Loading activity…</p>');else stamp.textContent='Updating…';try{const days=Number($('#analytics-range').value),data=await A.request('/api/analytics?days='+days);if(token!==analyticsToken||!A.user?.admin)return;U.patch(slot,renderAnalytics(data,days));stamp.classList.remove('is-error');stamp.textContent='Updated '+U.clock(Date.now())}catch(e){if(token===analyticsToken&&A.user?.admin){if(U.loaded(slot)){stamp.classList.add('is-error');stamp.textContent='Could not refresh: '+e.message}else U.show(slot,U.errorHtml(e.message,'analytics'))}await fail(e)}}
$('#analytics-range').onchange=()=>void loadAnalytics();$('#refresh-analytics').onclick=()=>void loadAnalytics();window.addEventListener('reposhelf-account',gate);
setInterval(()=>{if(A.user?.admin&&activeTab==='analytics'&&!document.hidden)void loadAnalytics()},60000);

/* ---------- tabs and attention ---------- */
function activateTab(tab,focus=true){if(!TABS.includes(tab)||!A.user?.admin)return;activeTab=tab;for(const name of TABS)$('#'+name+'-panel').hidden=name!==tab;document.querySelectorAll('.admin-tabs [data-admin-tab]').forEach(button=>{const on=button.dataset.adminTab===tab;button.classList.toggle('active',on);if(on){button.setAttribute('aria-current','page');button.scrollIntoView({inline:'nearest',block:'nearest'})}else button.removeAttribute('aria-current')});history.replaceState(null,'','/admin.html'+(tab==='editorial'?'':'?tab='+tab));message('');if(focus)$('#'+tab+'-heading')?.focus({preventScroll:true});if(tab==='sync')void loadSyncLog();if(tab==='analytics')void loadAnalytics();if(tab==='users')void loadUsers();if(tab==='help')void loadHelp()}
function syncFlag(data){const h=data.health;if(!h)return;const bad=(h.alerts||[]).some(a=>a.level==='error'),warn=h.state!=='healthy'||data.freshness?.overdue;U.flag('sync',bad?'bad':warn?'warn':null,bad?'a sync failed':'needs attention')}
async function loadAttention(){const token=++attentionToken,live=()=>token===attentionToken&&A.user?.admin,quiet=async fn=>{try{await fn()}catch{}};
 await Promise.all([quiet(async()=>{const d=await A.request('/api/editorial?action=reports&status=open&offset=0');if(live()){const n=d.items.length;U.flag('reports',n?'warn':null,n+(d.nextOffset!==null?'+':'')+' open')}}),quiet(async()=>{const d=await A.request('/api/sync-log?page=1');if(live())syncFlag(d)})]);
 await quiet(async()=>{const d=await A.request('/api/editorial?action=quality&offset=0&issue=&q=');if(live()){const n=(d.targets||[]).filter(t=>!t.met).length;U.flag('quality',n?'warn':null,n+' launch target'+(n===1?'':'s')+' not met')}})}
window.RepoAdminAttention=loadAttention;

/* ---------- users ---------- */
function renderUsers(){const slot=$('#users-content'),admins=users.filter(u=>u.admin).length;U.show(slot,users.length?`<p class="analytics-caption">${users.length.toLocaleString()} user${users.length===1?'':'s'} shown${userCursor?' so far':''} · ${admins} administrator${admins===1?'':'s'}</p><div class="help-table-wrap"><table class="analytics-table users-table"><thead><tr><th>User</th><th>Role</th><th>Last sign-in</th><th>Access</th></tr></thead><tbody>${users.map(person=>`<tr><td><strong>${esc(person.username==='GitHub user'?person.username:'@'+person.username)}${person.id===A.user?.id?' · You':''}</strong><small>GitHub ID ${esc(person.github_id)} · <span title="${esc(person.id)}">account ${esc(String(person.id).slice(0,8))}…</span></small></td><td>${person.admin?U.pill('administrator','Administrator','ok'):U.pill('member','Member','neutral')}</td><td>${person.last_sign_in_at&&Number.isFinite(Date.parse(person.last_sign_in_at))?esc(new Date(person.last_sign_in_at).toLocaleDateString()):'Never'}</td><td>${person.id===A.user?.id?'<span class="small">Your role is protected</span>':`<button class="button outline${person.admin?' danger':''}" data-role-user="${person.id}" ${busy?'disabled':''}>${person.admin?'Remove admin':'Grant admin'}</button>`}</td></tr>`).join('')}</tbody></table></div>`:`<p class="chart-empty">${$('#user-search').value.trim()?'No signed-in users match this search.':'No one has signed in with GitHub yet.'}</p>`);$('#more-users').hidden=!userCursor}
async function loadUsers(append=false){const token=++userToken,q=$('#user-search').value.trim();if(!append){users=[];userCursor=null;U.show($('#users-content'),'<p class="loading-note">Loading users…</p>');$('#more-users').hidden=true}try{const params=new URLSearchParams({q});if(append&&userCursor)params.set('cursor',userCursor);const data=await A.request('/api/admin-users?'+params);if(token!==userToken||!A.user?.admin)return;users=append?[...users,...data.items]:data.items;userCursor=data.nextCursor;renderUsers()}catch(e){if(token===userToken)U.show($('#users-content'),U.errorHtml(e.message,'users')+'<button class="button outline" data-admin-tab="help">Open Help</button>');await fail(e)}}
async function changeRole(id){const person=users.find(u=>u.id===id);if(!person||busy)return;const makeAdmin=!person.admin;if(!confirm(`${makeAdmin?'Grant administrator access to':'Remove administrator access from'} @${person.username} (GitHub ID ${person.github_id})?${makeAdmin?' They will be able to edit the store, view analytics and manage roles.':''}`))return;await task(async()=>{renderUsers();try{await A.request('/api/admin-users',{method:'PUT',body:JSON.stringify({id,admin:makeAdmin,expectedAdmin:person.admin})})}catch(e){if(e.status===409)await loadUsers();throw e}await loadUsers();message(makeAdmin?'Administrator access granted. The user can reload to see the admin menu.':'Administrator access removed.')});renderUsers()}
async function loadHelp(){const slot=$('#help-content');if(!U.loaded(slot))U.show(slot,'<p class="loading-note">Checking connection settings…</p>');try{const setup=await A.request('/api/admin-users?action=setup');if(!A.user?.admin)return;U.patch(slot,RepoAdminHelp.render(setup))}catch(e){if(!U.loaded(slot))U.show(slot,U.errorHtml(e.message,'help'));await fail(e)}}
$('#user-search').oninput=()=>{clearTimeout(userSearchTimer);userSearchTimer=setTimeout(()=>void loadUsers(),300)};$('#more-users').onclick=()=>void loadUsers(true);

/* ---------- sync log ---------- */
function renderSyncDeployment(deployment){if(!deployment)return '';const tone=deployment.state==='blocked'?'bad':deployment.state==='ready'?'ok':'warn';return `<section class="analytics-box sync-deploy tone-${tone}"><div class="panel-heading"><h3>${deployment.state==='blocked'?'Live deployment is blocked':deployment.state==='ready'?'Latest main deployment completed':deployment.state==='pending'?'Live deployment is pending':'Live deployment status unavailable'}</h3>${U.pill(deployment.state,deployment.state,tone)}</div><p class="analytics-caption">${esc(deployment.description)}${deployment.state==='blocked'?' Syncs can save records and screenshots to GitHub while the live site keeps serving an older catalogue.':''}</p><a href="${esc(deployment.url)}" target="_blank" rel="noopener">Inspect deployment ↗</a></section>`}
function renderSyncWork(run){const work=run.work,partial=run.phase&&run.phase!=='complete'?`<p class="analytics-caption"><strong>Partial results</strong> · This ${run.phase==='cleanup'?'run is in cleanup':'run is still discovering'}, so demo and screenshot totals may change before it finishes.</p>`:'';if(!work)return partial;
 const plan=work.discovery,browser=work.browser,after=work.coverageAfter,before=work.coverageBefore;
 const coverage=after?'<details><summary>Catalogue quality and remaining work</summary><div class="help-table-wrap"><table class="analytics-table"><thead><tr><th>Coverage</th><th>Before</th><th>After</th><th>Processing target</th><th>Still missing</th></tr></thead><tbody>'+[['Repository checks','repositoryChecks',after.available],['Conclusive demo checks','demoChecks',after.available],['Demo screenshots','screenshots',after.visible]].map(([label,key,total])=>'<tr><td>'+label+'</td><td>'+(before?Number(before[key]).toLocaleString():'—')+'</td><td>'+Number(after[key]).toLocaleString()+' / '+Number(total).toLocaleString()+'</td><td>'+Number(after.targets?.[key]??0).toLocaleString()+'</td><td>'+Number(after.pending?.[key]??Math.max(0,total-after[key])).toLocaleString()+'</td></tr>').join('')+'</tbody></table></div></details>':'';
 const discovery=plan?'<p class="analytics-caption"><strong>'+(plan.ready?'New discovery enabled':'New discovery paused')+'</strong> · '+esc(plan.ready?'Batches requested: '+plan.githubBatch+' GitHub candidates, '+plan.spacesBatch+' Spaces, '+plan.curatedBatch+' curated candidates and '+plan.communityBatch+' community candidates.':(plan.reasons||[]).join(' ')||'Existing catalogue quality is below its discovery targets.')+'</p>':'';
 const cycle=browser?'<p class="analytics-caption"><strong>'+(browser.due?'Browser batch requested':'Browser batch skipped')+'</strong> · '+esc(browser.reason||'')+(!browser.due&&browser.nextDueAt?' Next window: '+esc(new Date(browser.nextDueAt).toLocaleString())+'.':'')+'</p>':'';
 const backlog=after?.browserBacklog,backlogHtml=backlog?'<div class="metric-grid">'+metric(backlog.demo.never,'Demo checks never attempted')+metric(backlog.screenshot.never,'Screenshots never attempted')+metric(backlog.demo.repeated,'Repeated demo failures')+metric(backlog.screenshot.repeated,'Repeated screenshot failures')+'</div><p class="small">Repeated means at least three consecutive failures for the current demo URL. These pages retry after a backoff; saved evidence is preserved.</p>':'';
 const gains=work.qualityGains,publication=after?.publication;const admission=publication?'<div class="metric-grid">'+metric(publication.published,'Published quality-ready')+metric(publication.pending,'Pending admission')+metric(publication.quarantined,'Quarantined for repair')+metric(after.workingDemos,'Confirmed working demos')+'</div><p class="small">Discovery continues into a pending pool. Public browsing requires a working demo, a captured demo screenshot and fresh repository evidence. Quarantined records remain saved and retry later.</p>':'';const net=gains?'<div class="metric-grid">'+metric(gains.screenshots,'Net screenshot coverage gain')+metric(gains.demoChecks,'Net conclusive-check gain')+metric(gains.workingDemos,'Net working-demo gain')+metric(gains.published,'Net published-project gain')+'</div>':'';return partial+discovery+admission+net+cycle+coverage+backlogHtml}
function renderSyncYield(d){if(!d?.sourceYield)return '';return '<div class="help-table-wrap"><table class="analytics-table"><thead><tr><th>Source</th><th>Inspected</th><th>New records</th><th>Demos found / refreshed</th><th>Errors</th></tr></thead><tbody>'+Object.entries(d.sourceYield).map(([source,row])=>'<tr><td>'+esc(source)+'</td><td>'+Number(row.inspected||0).toLocaleString()+'</td><td>'+Number(row.added||0).toLocaleString()+'</td><td>'+Number(row.found||0).toLocaleString()+'</td><td>'+Number(row.errors||0).toLocaleString()+'</td></tr>').join('')+'</tbody></table></div><p class="small">New records enter validation; they are published only after their demo and screenshot qualify.</p>'+(d.queryYield?.length?'<details><summary>Yield by search query</summary><div class="help-table-wrap"><table class="analytics-table"><thead><tr><th>Query</th><th>Page</th><th>Inspected</th><th>New records</th><th>Demos</th><th>Cached</th></tr></thead><tbody>'+d.queryYield.map(row=>'<tr><td>'+esc(row.query)+'</td><td>'+Number(row.page)+'</td><td>'+Number(row.inspected||0)+'</td><td>'+Number(row.added||0)+'</td><td>'+Number(row.found||0)+'</td><td>'+Number(row.cacheHits||0)+'</td></tr>').join('')+'</tbody></table></div></details>':'');}
const statList=rows=>'<dl class="stat-list">'+rows.map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+v+'</dd></div>').join('')+'</dl>';
function renderSyncStageDetails(stage){const d=stage.details;if(stage.id==='sources'&&d?.sourceYield)return '<details><summary>Spaces and curated discovery yield</summary>'+renderSyncYield(d)+'</details>';if(stage.id==='catalog'&&d)return '<details><summary>GitHub discovery debugging details</summary>'+statList([['Repository checks',Number(d.repositoryChecks).toLocaleString()],['Discovery candidates checked',Number(d.candidatesChecked).toLocaleString()+' of '+Number(d.candidateLimit)+' allowed'],['Demos found or refreshed',Number(d.demosFound).toLocaleString()],['Cached checks reused',Number(d.cacheHits).toLocaleString()],['Search requests',Number(d.searchQueries).toLocaleString()]])+renderSyncYield(d)+(d.repositoryPlan?'<h4 class="stat-heading">Repository refresh</h4>'+statList([['Due for a check',Number(d.repositoryDue).toLocaleString()],['Selected this run',Number(d.repositorySelected).toLocaleString()],['Still due afterwards',Number(d.repositoryRemainingDue).toLocaleString()],['Checked in the last '+(d.repositoryObserved48h!=null?'48':'24')+' hours',Number(d.repositoryObserved48h??d.repositoryObserved24h).toLocaleString()+' available records'],['Run size',Number(d.repositoryPlan.limit)+' checks, keeping '+Number(d.repositoryPlan.reserve)+' GitHub requests in reserve']])+'<p class="analytics-caption">'+(d.repositoryPlan.dailyCapacitySufficient?'At this pace, daily capacity covers the whole catalogue.':'At this pace, daily capacity is smaller than the catalogue. More GitHub API allowance or more runs may be needed.')+(d.repositoryStopReason?' This run stopped early: '+esc(d.repositoryStopReason.replaceAll('_',' '))+'.':'')+'</p>':'')+(d.repositoryPaused?'<p class="small">Repository checks stopped early after authentication or rate limiting; saved entries were retained.</p>':'')+(d.searchPaused?'<p class="small">Search paused · HTTP '+esc(d.searchPaused.status??'unknown')+' · rate-limit allowance remaining: '+esc(d.searchPaused.rateRemaining??'unknown')+'.</p>':'')+'</details>';if(!d||!Number.isFinite(d.attempted))return '';
 const adaptiveNote=d.adaptive?'<p class="small">Shared browser time budget: '+Math.round(Number(d.budgetMs)/60000)+' minutes · running '+Number(d.adaptive.limit)+' pages at once (up to '+Number(d.adaptive.max)+') · '+Number(d.pool?.browserLaunches||0)+' browser launches, '+Number(d.pool?.workerStarts||0)+' worker starts and '+Number(d.pool?.workerRestarts||0)+' restarts, each page in a fresh isolated session'+(d.resources?' · '+Number(d.resources.availableMB)+' MB memory free ('+esc(d.resources.source)+')':'')+'.</p>':'';
 const recovery=d.recoveryPasses?'<table class="analytics-table"><thead><tr><th>Recovery pass</th><th>Attempted</th><th>Captured</th><th>Net screenshot gain</th><th>Net check gain</th></tr></thead><tbody>'+d.recoveryPasses.map(p=>'<tr><td>'+Number(p.pass)+'</td><td>'+Number(p.attempted)+'</td><td>'+Number(p.captured)+'</td><td>'+Number(p.netScreenshots)+'</td><td>'+Number(p.netDemoChecks)+'</td></tr>').join('')+'</tbody></table>':'';const reasons=Object.entries(d.reasons||{});
 return '<details><summary>'+esc(stage.name)+' debugging details</summary>'+adaptiveNote+recovery+'<p class="analytics-caption">'+Number(d.due).toLocaleString()+' due · '+Number(d.selected).toLocaleString()+' selected ('+(['time_budget','shared_time_budget'].includes(d.mode)?'time budget; no fixed batch cap':'batch limit '+Number(d.limit))+') · '+Number(d.attempted).toLocaleString()+' attempted · '+Number(d.deferred||0).toLocaleString()+' selected but deferred · '+Number(d.remainingDue).toLocaleString()+' still due'+(d.durationMs!=null?' · '+Math.round(d.durationMs/1000)+' seconds':'')+(d.complete===false?' · Last saved progress before interruption':'')+'</p>'+'<div class="metric-grid">'+metric(d.working,'Pages loaded')+(stage.id==='previews'?metric(d.captured,'Screenshots captured'):'')+'</div>'+(reasons.length?'<ul class="small">'+reasons.map(([reason,count])=>'<li>'+esc(reason.replaceAll('_',' '))+': '+Number(count)+'</li>').join('')+'</ul>':'')+(d.examples?.length?'<p class="small">Sample listings to investigate:</p><ul class="small">'+d.examples.map(e=>'<li>'+esc(e.project)+' · '+esc(e.reason.replaceAll('_',' '))+'</li>').join('')+'</ul>':'')+'</details>'}
function renderSyncHealth(health,freshness){if(!health)return '';const alerts=health.alerts||[],hasError=alerts.some(a=>a.level==='error'),overdue=freshness?.overdue,tone=hasError?'bad':health.state==='healthy'&&!overdue?'ok':'warn',title=health.state==='healthy'?overdue?'A successful sync is overdue':'Syncs are up to date':health.state==='unknown'?'Sync status needs checking':'Syncs need attention',last=freshness?.lastSuccessAt?`Last successful sync ${esc(U.ago(freshness.lastSuccessAt))} (${esc(new Date(freshness.lastSuccessAt).toLocaleString())}).`:'No successful sync appears in the current workflow history.';
 return `<section class="analytics-box sync-health tone-${tone}"><div class="panel-heading"><h3>${title}</h3>${U.pill(tone==='ok'?'healthy':tone==='bad'?'failed':'attention',alerts.length?alerts.length+' notice'+(alerts.length===1?'':'s'):'No active alerts',tone)}</div><p class="analytics-caption">${last}${overdue?' More than three hours have passed since the last successful run. Review the latest workflow and its publication steps.':''}</p>${alerts.map(a=>`<article class="sync-alert ${a.level==='error'?'error':''}" role="status"><h4>${esc(a.title)}</h4><p>${esc(a.message)}</p><a href="${esc(a.url)}" target="_blank" rel="noopener">Inspect workflow ↗</a></article>`).join('')}<details class="sync-recovery"><summary>Run a sync or retry safely</summary><ol><li>Open <a href="${esc(health.workflowUrl)}" target="_blank" rel="noopener">GitHub Actions ↗</a> and check that no catalogue sync is already running or queued.</li><li>For a failed run, inspect its log. Fix configuration or permissions before retrying those errors. Temporary source failures normally retry automatically.</li><li>Use <strong>Run workflow</strong> on the <strong>main</strong> branch for a fresh scan. Enable <strong>Refresh demo health and screenshots now</strong> only when an immediate browser batch is needed.</li><li>Return here and refresh. Completed syncs are saved for daily publication. Use Publish now when you want them live sooner; check the deployment status afterward.</li></ol><p class="analytics-caption">These alerts appear in the admin dashboard; email and push notifications are not configured. Checked ${esc(new Date(health.checkedAt).toLocaleString())}.</p></details></section>`}
function renderSyncPublication(publication,freshness,runs=[]){if(catalogueRequest?.phase==='accepted'&&catalogueRequest.action==='sync'){const started=runs.find(r=>Date.parse(r.startedAt)>=catalogueRequest.startedAt-1000);if(started)catalogueRequest={...catalogueRequest,phase:'confirmed',message:'Sync '+started.id+' is '+started.status.replaceAll('_',' ')+'. Progress appears below.'}}const running=runs.some(r=>RUNNING.includes(r.status)),blocked=publication?.controlConfigured===false||['sending','accepted'].includes(catalogueRequest?.phase)||running,when=value=>value?esc(new Date(value).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'})):'Unavailable';catalogueBlockedReason=publication?.controlConfigured===false?'In-app sync needs a GitHub Actions token. Set REPOSHELF_ACTIONS_TOKEN in Vercel with Actions read/write access to RepoShelf, then redeploy.':running?'A sync is already running or queued. Its progress appears below; wait for it to finish.':null;
 return `<section class="analytics-box catalogue-publication"><div class="panel-heading"><h3>Catalogue publication</h3><div class="row-tile-actions"><button class="button outline" id="catalogue-sync-now" type="button" data-workflow-blocked="${blocked}" aria-describedby="catalogue-publish-status">Sync now</button><button class="button outline" id="catalogue-publish-now" type="button" data-workflow-blocked="${blocked}" aria-describedby="catalogue-publish-status">Publish now</button></div></div><p class="sync-action-status" id="catalogue-publish-status" role="status">${esc(catalogueRequest?.message||catalogueBlockedReason||'')}</p><p class="analytics-caption">Syncs save records and screenshots without deploying. Publish now sends saved changes to Vercel; it does not start a scan.</p><div class="metric-grid"><div><strong>Next scheduled sync</strong><p>${when(publication?.nextSyncAt)}</p></div><div><strong>Next scheduled deployment</strong><p>${when(publication?.nextPublicationAt)}</p></div><div><strong>Last successful sync</strong><p>${when(freshness?.lastSuccessAt)}</p></div><div><strong>Last catalogue publication</strong><p>${publication?.lastPublishedAt?when(publication.lastPublishedAt):'Not recorded yet'}</p></div></div><p class="small">Times shown in ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}. The normal sync schedule is every two hours. During launch acceleration, extra runs are scheduled at 17 and 47 minutes past the hour, capped at 24 extra runs per rolling day. Publication is daily at 06:35 UTC, with one extra publication when the initial 5,000 published milestone is reached. GitHub may delay scheduled starts. A deployment follows when saved content has changed.</p>${publication?.controlConfigured===false?'<p class="small">In-app sync and publication require REPOSHELF_ACTIONS_TOKEN in Vercel, with Actions read/write access to RepoShelf. <button type="button" class="help-inline-button" data-admin-tab="help">Setup help</button>. You can run the workflow on GitHub meanwhile.</p>':blocked&&!catalogueRequest?'<p class="small">A sync is active. Wait for it to finish before syncing or publishing.</p>':''}<a href="https://github.com/sparx1981/RepoShelf/actions/workflows/publication.yml" target="_blank" rel="noopener">Publication history / Run workflow ↗</a></section>`}
function renderSyncRun(run,index){const c=run.counts,pill=U.pill(run.status),trigger=`${esc(run.trigger)} · Run ${esc(run.id)}${run.attempt>1?' · Attempt '+Number(run.attempt):''}`,waiting=['queued','waiting','pending','requested'].includes(String(run.status).toLowerCase()),live=RUNNING.includes(run.status)&&!waiting,span=waiting?null:U.duration(run.startedAt,run.finishedAt||(live?Date.now():null)),took=`<span class="run-duration"><small>${live?'Running for':'Duration'}</small>${span?esc(span):waiting?'Not started':'Not recorded'}</span>`,delta=c?`+${Number(c.added).toLocaleString()} added · ${Number(c.updated).toLocaleString()} updated · ${Number(c.after).toLocaleString()} total`:'No record counts';
 return `<details class="analytics-box sync-run" ${index===0?'open':''}><summary class="sync-run-summary"><span class="run-when"><strong>${esc(new Date(run.startedAt).toLocaleString())}</strong><small>${trigger}</small></span>${pill}${took}<span class="run-delta">${delta}</span></summary><div class="sync-run-body">${run.diagnostics?`<p class="analytics-caption">${esc(run.diagnostics.message)}</p>`:''}${window.RepoSyncProgress?.render(run.browserProgress)||''}${renderSyncWork(run)}${c?`<div class="metric-grid">${metric(c.added,'Records added')}${metric(c.updated,'Records updated')}${metric(c.after,'Total records')}${metric(c.withDemo??null,'With demo page')}${metric(run.stages?.find(s=>s.id==='previews')?.details?.captured??null,'Screenshots captured')}${metric(run.temporaryFailures,'Checks awaiting retry')}</div><p class="small">${Number(c.before).toLocaleString()} before this run · ${Number(c.removed).toLocaleString()} removed or merged${c.withDemo==null?' · Demo-page counts were not recorded for this run.':''}</p>`:`<p class="analytics-caption">${run.diagnostics?.kind==='cancelled_before_start'?'No records were scanned in this run.':'Record-change counts were not recorded for this run.'}</p>`}${run.finishedAt?`<p class="small">Finished ${esc(new Date(run.finishedAt).toLocaleString())}${span?' · took '+esc(span):''}</p>`:''}${run.stages?.length?`<details><summary>Stage results</summary><div class="help-table-wrap"><table class="analytics-table"><thead><tr><th>Stage</th><th>Result</th><th>Attempted</th><th>Checks awaiting retry</th><th>Warnings</th><th>Unavailable</th><th>Inconclusive</th></tr></thead><tbody>${run.stages.map(stage=>`<tr><td>${esc(stage.name)}</td><td>${U.pill(stage.status)}</td><td>${Number(stage.checked||0)}</td><td>${Number(stage.temporaryFailures||0)}</td><td>${Number(stage.warnings||0)}</td><td>${Number(stage.unavailableResponses||0)}</td><td>${Number(stage.inconclusiveChecks||0)}</td></tr>`).join('')}</tbody></table></div></details>${run.stages.map(renderSyncStageDetails).join('')}`:''}<p><a href="${esc(run.url)}" target="_blank" rel="noopener">View full workflow log ↗</a></p></div></details>`}
async function loadSyncLog(quiet=false){if(syncLoading||catalogueRequest?.phase==='sending')return;syncLoading=true;const slot=$('#sync-content'),stamp=$('#sync-updated'),button=$('#refresh-sync'),token=++syncToken;if(!U.loaded(slot))U.show(slot,'<p class="loading-note">Loading sync history…</p>');else if(!quiet)stamp.textContent='Updating…';button.disabled=true;button.setAttribute('aria-busy','true');try{const data=await A.request('/api/sync-log?page='+syncPage);if(token!==syncToken||!A.user?.admin)return;if(catalogueRequest?.phase==='accepted'&&catalogueRequest.action==='publish'){try{const history=await A.request('/api/sync-log?action=publication-status');const started=history.runs?.find(r=>Date.parse(r.startedAt)>=catalogueRequest.startedAt-1000);if(started)catalogueRequest={...catalogueRequest,phase:'confirmed',message:'Publication '+started.id+' is '+started.status.replaceAll('_',' ')+'. Check deployment status below.'}}catch{}}
 syncAutoRefresh=catalogueRequest?.phase==='accepted'||data.runs.some(r=>RUNNING.includes(r.status));
 U.patch(slot,renderSyncHealth(data.health,data.freshness)+renderSyncDeployment(data.deployment)+renderSyncPublication(data.publication,data.freshness,data.runs)+(data.notice?`<p class="analytics-caption">${esc(data.notice)}</p>`:'')+(data.runs.length?data.runs.map(renderSyncRun).join('')+'<p class="analytics-caption sync-footnote">With demo page counts available listings with usable demo links after a sync; it does not guarantee every demo feature works. Checks awaiting retry were inconclusive and retry automatically; they do not mean the workflow failed.</p>':'<p class="chart-empty">No sync runs are available yet.</p>'));
 syncFlag(data);syncLoadedAt=Date.now();stamp.classList.remove('is-error');stamp.textContent='Updated '+U.clock(syncLoadedAt);$('#sync-prev').hidden=syncPage===1;$('#sync-next').hidden=!data.hasMore}catch(e){if(token===syncToken&&A.user?.admin){if(U.loaded(slot)){stamp.classList.add('is-error');stamp.textContent='Could not refresh: '+e.message}else U.show(slot,U.errorHtml(e.message,'sync'))}await fail(e)}finally{syncLoading=false;button.disabled=false;button.removeAttribute('aria-busy')}}
setInterval(()=>{if(A.user?.admin&&activeTab==='sync'&&!document.hidden&&!syncLoading&&syncPage===1&&(syncAutoRefresh||Date.now()-syncLoadedAt>=60000))void loadSyncLog(true)},30000);
$('#refresh-sync').onclick=()=>void loadSyncLog();$('#sync-prev').onclick=()=>{syncPage=Math.max(1,syncPage-1);void loadSyncLog()};$('#sync-next').onclick=()=>{syncPage++;void loadSyncLog()};
async function requestCatalogueWorkflow(action){const show=text=>{const status=$('#catalogue-publish-status');if(status){status.textContent=text;status.scrollIntoView({block:'nearest'})}};if(['sending','accepted'].includes(catalogueRequest?.phase)){show(catalogueRequest.message);return}if(catalogueBlockedReason){catalogueRequest={action,phase:'blocked',message:catalogueBlockedReason};show(catalogueBlockedReason);return}if(action==='publish'&&!confirm('Publish the saved catalogue to the live site now? This starts a deployment.'))return;catalogueRequest={action,phase:'sending',startedAt:Date.now(),message:action==='sync'?'Requesting a sync from GitHub…':'Requesting catalogue publication…'};const update=()=>{const status=$('#catalogue-publish-status');if(status)status.textContent=catalogueRequest.message;for(const id of ['catalogue-sync-now','catalogue-publish-now']){const control=$('#'+id),on=String(['sending','accepted'].includes(catalogueRequest.phase));if(control)control.setAttribute('data-workflow-blocked',on)}};update();try{const result=await A.request('/api/sync-log?action=publish',{method:'POST',body:JSON.stringify({action})});if(!result.requested)throw Error('GitHub did not confirm the workflow request. Refresh the history before retrying.');catalogueRequest.phase='accepted';catalogueRequest.message=result.reason+' GitHub has accepted the request; waiting for it to appear in workflow history.';syncAutoRefresh=true;update();setTimeout(()=>{if(A.user?.admin&&activeTab==='sync')void loadSyncLog(true)},3000)}catch(error){catalogueRequest.phase='error';catalogueRequest.message=error.message;update()}}

gate();
